def main():
    rows=json.loads((ROOT/'tables/issue_registry.json').read_text())
    for r in rows:
        status,action,files,result,remaining=RESOLUTIONS[r['id']]
        r.update(status=status,action_taken=action,files_changed=files.split(';'),new_result=result,remaining_issue=remaining)
    (ROOT/'tables/issue_registry.json').write_text(json.dumps(rows,indent=2)+'\n');registry.main()
    out=['# Response to the complete scientific review','This is an internal scientific response, not a message sent to referees. The full review was read before changes. All 19 substantive concerns are tracked below; the complete 59-result and 20-assumption audits remain preserved and feed the dependency audit. P0/P1 correctness, methods and experiments were addressed before rewriting the narrative.','## Response matrix','The CSV/JSON matrix includes review location, scientific type, proposed action, actual action, files changed, new result and remaining issue.','| ID / priority | Concern | Status |','|---|---|---|']
    for r in rows:out.append(f'| {r["id"]} / {r["severity"]} | {r["review_concern"]} | {r["status"]} |')
    for r in rows:
        assessment=('The concern identifies an unresolved research extension. The focused manuscript can state the existing results without claiming this extension.' if r['id'].startswith('T') else 'The concern is valid. Its scope must be distinguished from any stronger unproved interpretation.')
        if r['id']=='F04':assessment='The empirical concern is valid. The prior P1 theorem asserted expected length, not midpoint MSE, so no false P1 theorem is being repaired. The estimator output nevertheless required a substantive correction.'
        if r['id']=='F05':assessment='The criticism is valid as a design confounding issue. A supplied norm bound chosen for each prescribed simulation class is not data leakage; it simply changes the question being measured.'
        if r['id']=='D01':assessment='No invalid real-data result existed to repair. Adding an arbitrary dataset would not establish the required sampling model or prescribed target. A real-data extension remains unavailable rather than being marked scientifically resolved.'
        out.extend([f'## {r["id"]}: {r["review_concern"]}',f'**Review concern:** {r["review_concern"]}. The precise original location is recorded in registry row {r["id"]}.',f'**Assessment:** {assessment}',f'**Action:** {r["action_taken"]}',f'**Technical resolution / new evidence:** {r["new_result"]}',f'**Manuscript and artifact changes:** '+', '.join(f'[{Path(p).name}]({p})' for p in r['files_changed'])+'.',f'**Remaining issue:** {r["remaining_issue"]}',f'**Status:** {r["status"]}.'])
    (ROOT/'response_to_review.md').write_text('\n\n'.join(out).replace('|\n\n|','|\n|')+'\n')
    cross=[
    ('Full review before edits','logs/review_read_manifest.json; issue_registry.md'),('Scientific classification','tables/issue_registry.csv'),('Correctness before narrative','theory/revision_audit.md; results/saved_corrections.json'),('Identifiability','theory/revision_audit.md; main Section 2'),('Theorem dependency chains','theory/revision_audit.md; technical_supplement.pdf'),('Theorem status','theory/theorem_status.json: 59 retained PROVED + R1 PROVED'),('Assumption investigation','theory/revision_audit.md, seven assumption families; prior 20-family audit preserved'),('Rates and optimality','main Sections 2–5; full-data/marginal/class/algorithm distinctions'),('Mathematical novelty','novelty_and_baselines.md; main Section 3'),('Execute missing simulations','55 registered cases, all completed'),('Direct theorem tests','V03/V04 calibrations; V05 P1 normalized lengths; analytic rate plot labeled'),('Investigate contradiction','R1 proof and all-observation scalar reevaluation; exact Gaussian coverage miss'),('Strong/fair baselines','XCH source map; common data; oracle information marked'),('Real-data validity','D01 unresolved; no unsupported application'),('Better application if needed','No defensible dataset/target established; explicit future-work conditions'),('Computation and numerical error','C1 contract; 600 fixed-loading solves; fresh runtime/input accounting'),('Tuning','fixed budgets/tolerance; V04 independent scale calibration; paired allocations'),('Scientific fixes before claims','registered runs and completed analyses precede final abstract/main'),('Contribution statements','three final claims mapped to formal results and evidence'),('Abstract last','code/build_reports.py generates abstract after reading final checked tables'),('Theory interpretation','main Sections 2–6 explain budget/order/rank and scope'),('Technical organization','focused main paper plus complete technical supplement'),('Notation','paper/notation.md and consistent active sources'),('Reproducibility','reproduce.sh; raw results; seeds/configs/source manifests'),('Response matrix','tables/issue_registry.csv/json'),('Individual responses','response_to_review.md: all 19 concerns'),('Critical engagement','F04 length versus MSE; F05 class change versus leakage; D01; G2 impossibility'),('All affected outputs','303 saved interval cases reevaluated; 55 new cases; dependent figures/text regenerated'),('Downstream claims','new R1 and unchanged central-rate dependency audit'),('Figures and tables','six new vector figures, ten saved-study figures regenerated; numerical text generated'),('Negative findings','593 unresolved solves, weak XCH failure, cap-violation failure, rare losses preserved'),('Central contribution revisited','novelty_and_baselines.md and revision_summary.md'),('Journal fit','revision_summary.md compares requested venues'),('Second adversarial review','second_review.md'),('Residual classification','second_review.md and revision_summary.md'),('Specific limitations','main Discussion and revision_summary.md'),('Final A–J summary','revision_summary.md'),('Scientific before/after diff','revision_summary.md'),('Readiness checkpoint','second_review.md'),('Final verdict','B for focused theory paper; broader four-part research program remains open')]
